```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <cstdlib>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("wielokat.txt");
    int n;
    plik >> n;
    int x[100], y[100];
    for (int i = 0; i < n; i++)
        plik >> x[i] >> y[i];
    int sumPole = 0;
    double obwod = 0;
    double maxBok = 0, minBok = 1e9;
    int maxBokIdx = 1, minBokIdx = 1;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        sumPole += x[i] * y[j] - x[j] * y[i];
        double dx = x[j] - x[i], dy = y[j] - y[i];
        double d = sqrt(dx * dx + dy * dy);
        obwod += d;
        if (d > maxBok) { maxBok = d; maxBokIdx = i + 1; }
        if (d < minBok) { minBok = d; minBokIdx = i + 1; }
    }
    double pole = abs(sumPole) / 2.0;
    int collinear = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        int k = (i + 2) % n;
        int cross = (x[j] - x[i]) * (y[k] - y[i]) - (y[j] - y[i]) * (x[k] - x[i]);
        if (cross == 0) collinear++;
    }
    cout << fixed << setprecision(2);
    cout << "Pole: " << pole << endl;
    cout << "Obwod: " << obwod << endl;
    cout << "Najdluzszy bok: " << maxBokIdx << " (" << maxBok << ")" << endl;
    cout << "Najkrotszy bok: " << minBokIdx << " (" << minBok << ")" << endl;
    cout << "Wspoliniowe trojki: " << collinear << endl;
    return 0;
}
```

